    select round(avg(${columnName}),1) as avgData,round(min(${columnName}),1) minData,round(max(${columnName}),1) maxData,formatDateTime(transfer_time,'%Y-%m') day from ${tableName}
where maintain_plan_id = #{id}
 and transfer_time >= #{startTime}
 and transfer_time <= #{endTime}
 group by day;
